A leírt, teljes körű (konténer-orchestration + Nix + azonnali snapshot/branch + WebRTC+OT + Postgres/Redis + ACME/SSL + multi‑region) felhő-IDE ökoszisztéma **két fájlban**, külső függőségek nélkül nem építhető meg reálisan és biztonságosan “production-ready” módon. Az alábbiak viszont egy futtatható, bővíthető *referencia/MVP* alapot adnak két fájlban, és pontos illesztési pontokat hagynak a valódi Docker/Nix/Postgres/Redis/WebRTC/ACME komponensek későbbi bekötésére.

## Korlátok és célzott helyettesítések
A Nix valódi erőssége a deklaratív, izolált build és a reprodukálhatóság; ezt itt úgy modellezem, hogy a backend képes `nix develop`/`nix-shell` jellegű parancsokat futtatni, de a Nix-et magát nem tudja “beépíteni” egyetlen Go fájlba.[1]
A wildcard subdomain alapú reverse proxy routing NGINX-ben tipikusan `server_name *.example.org;` (vagy regex) mintákkal oldható meg; a backend ehhez csak konfiguráció‑generálást és target‑mappinget ad.[1]
A Go oldali WebRTC implementáció a gyakorlatban külső könyvtárakat használ (pl. Pion), ezért itt WebSocket-alapú kollaborációs csatornát adok OT‑szerű, szerver‑sorosított műveletekkel és “resync” fallbackkel.[2]

## backend.go (egyfájlos Go szerver)
Az alábbi egyetlen Go fájl: (1) projekt CRUD + snapshot/branch (hardlinkes “gyors másolat” ha a FS engedi), (2) JWT login, (3) WebSocket “sync” csatorna egyszerű szerver-sorosított műveletekkel, (4) WebSocket “terminal” (line‑based parancsfuttatás), (5) Nix manifest futtatás (ha a hoston elérhető), (6) deploy stub (NGINX snippet generálás), (7) AI agent stub (LLM hívás helye + Playwright futtatás helye snapshoton).

```go
// backend.go
package main

import (
	"bytes"
	"context"
	"crypto/hmac"
	"crypto/rand"
	"crypto/sha256"
	"encoding/base64"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"io/fs"
	"log"
	"mime"
	"net"
	"net/http"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"sort"
	"strconv"
	"strings"
	"sync"
	"time"
)

const (
	addr              = ":8080"
	dataRoot          = "./data"
	projectRoot       = dataRoot + "/projects"
	nginxOutRoot      = dataRoot + "/nginx"
	jwtTTL            = 12 * time.Hour
	maxBodyBytes      = 10 << 20
	wsMaxMessageBytes = 1 << 20
)

var (
	jwtKey = []byte(envOr("JWT_SECRET", "dev-secret-change-me"))
)

func main() {
	mime.AddExtensionType(".js", "application/javascript; charset=utf-8")
	mime.AddExtensionType(".css", "text/css; charset=utf-8")
	must(os.MkdirAll(projectRoot, 0o755))
	must(os.MkdirAll(nginxOutRoot, 0o755))

	s := newServer()
	mux := http.NewServeMux()

	// Static frontend (expects index.html in same directory)
	mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != "/" && r.URL.Path != "/index.html" {
			http.NotFound(w, r)
			return
		}
		http.ServeFile(w, r, "./index.html")
	})

	// REST-ish API
	mux.HandleFunc("/api/health", s.handleHealth)
	mux.HandleFunc("/api/auth/register", s.handleRegister)
	mux.HandleFunc("/api/auth/login", s.handleLogin)
	mux.HandleFunc("/api/auth/me", s.withAuth(s.handleMe))

	mux.HandleFunc("/api/projects", s.withAuth(s.handleProjects))
	mux.HandleFunc("/api/projects/", s.withAuth(s.handleProjectByID))

	mux.HandleFunc("/api/projects/", s.withAuth(s.handleProjectSubroutes)) // snapshot/files/term/sync/deploy/agent

	// Minimal GraphQL-style endpoint (optional client use)
	mux.HandleFunc("/graphql", s.withAuth(s.handleGraphQL))

	// WebSocket endpoints
	mux.HandleFunc("/api/ws/sync", s.withAuth(s.handleWSSync))
	mux.HandleFunc("/api/ws/term", s.withAuth(s.handleWSTerm))

	// Regional routing hint (stub)
	mux.HandleFunc("/api/region", s.handleRegion)

	h := withLogging(withLimits(mux))

	srv := &http.Server{
		Addr:              addr,
		Handler:           h,
		ReadHeaderTimeout: 10 * time.Second,
	}
	log.Printf("listening on %s (go=%s, os=%s)", addr, runtime.Version(), runtime.GOOS)
	log.Fatal(srv.ListenAndServe())
}

/* ----------------------------- core server ----------------------------- */

type server struct {
	mu sync.RWMutex

	usersByEmail map[string]*user
	usersByID    map[string]*user

	projects map[string]*project

	// project KV store (per project)
	kv map[string]map[string]string

	// in-memory docs for sync channel: projectID -> filePath -> doc
	docs map[string]map[string]*docState

	// ws hubs
	syncHub *syncHub
	termHub *termHub
}

func newServer() *server {
	s := &server{
		usersByEmail: map[string]*user{},
		usersByID:    map[string]*user{},
		projects:     map[string]*project{},
		kv:           map[string]map[string]string{},
		docs:         map[string]map[string]*docState{},
	}
	s.syncHub = newSyncHub(s)
	s.termHub = newTermHub(s)
	go s.syncHub.run()
	go s.termHub.run()

	s.loadFromDisk()
	return s
}

/* ----------------------------- persistence ----------------------------- */

type persistState struct {
	Users    []*user           `json:"users"`
	Projects []*project        `json:"projects"`
	KV       map[string]kvItem `json:"kv"`
}

type kvItem struct {
	Items map[string]string `json:"items"`
}

func (s *server) statePath() string { return dataRoot + "/state.json" }

func (s *server) loadFromDisk() {
	b, err := os.ReadFile(s.statePath())
	if err != nil {
		return
	}
	var ps persistState
	if json.Unmarshal(b, &ps) != nil {
		return
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	for _, u := range ps.Users {
		s.usersByEmail[u.Email] = u
		s.usersByID[u.ID] = u
	}
	for _, p := range ps.Projects {
		s.projects[p.ID] = p
	}
	s.kv = map[string]map[string]string{}
	for pid, item := range ps.KV {
		s.kv[pid] = item.Items
	}
}

func (s *server) saveToDisk() {
	s.mu.RLock()
	ps := persistState{
		Users:    []*user{},
		Projects: []*project{},
		KV:       map[string]kvItem{},
	}
	for _, u := range s.usersByID {
		ps.Users = append(ps.Users, u)
	}
	for _, p := range s.projects {
		ps.Projects = append(ps.Projects, p)
	}
	for pid, m := range s.kv {
		cp := map[string]string{}
		for k, v := range m {
			cp[k] = v
		}
		ps.KV[pid] = kvItem{Items: cp}
	}
	s.mu.RUnlock()

	sort.Slice(ps.Users, func(i, j int) bool { return ps.Users[i].Email < ps.Users[j].Email })
	sort.Slice(ps.Projects, func(i, j int) bool { return ps.Projects[i].Name < ps.Projects[j].Name })

	b, _ := json.MarshalIndent(ps, "", "  ")
	_ = os.WriteFile(s.statePath(), b, 0o600)
}

/* ----------------------------- models ----------------------------- */

type user struct {
	ID           string `json:"id"`
	Email        string `json:"email"`
	PasswordHash string `json:"-"`
	CreatedAt    int64  `json:"createdAt"`
}

type project struct {
	ID        string `json:"id"`
	Name      string `json:"name"`
	OwnerID   string `json:"ownerId"`
	CreatedAt int64  `json:"createdAt"`
	UpdatedAt int64  `json:"updatedAt"`
}

func (p *project) workDir() string     { return filepath.Join(projectRoot, p.ID, "work") }
func (p *project) snapsDir() string    { return filepath.Join(projectRoot, p.ID, "snaps") }
func (p *project) manifestPath() string { return filepath.Join(p.workDir(), "nix.manifest.json") }

/* ----------------------------- middleware ----------------------------- */

func withLogging(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		start := time.Now()
		ww := &wrapW{ResponseWriter: w, status: 200}
		next.ServeHTTP(ww, r)
		log.Printf("%s %s -> %d (%s)", r.Method, r.URL.Path, ww.status, time.Since(start))
	})
}

type wrapW struct {
	http.ResponseWriter
	status int
}

func (w *wrapW) WriteHeader(code int) {
	w.status = code
	w.ResponseWriter.WriteHeader(code)
}

func withLimits(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		r.Body = http.MaxBytesReader(w, r.Body, maxBodyBytes)
		next.ServeHTTP(w, r)
	})
}

/* ----------------------------- helpers ----------------------------- */

func must(err error) {
	if err != nil {
		panic(err)
	}
}

func envOr(k, d string) string {
	v := strings.TrimSpace(os.Getenv(k))
	if v == "" {
		return d
	}
	return v
}

func nowUnix() int64 { return time.Now().Unix() }

func writeJSON(w http.ResponseWriter, code int, v any) {
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.WriteHeader(code)
	_ = json.NewEncoder(w).Encode(v)
}

func readJSON(r *http.Request, dst any) error {
	dec := json.NewDecoder(r.Body)
	dec.DisallowUnknownFields()
	return dec.Decode(dst)
}

func randID(prefix string) string {
	var b [16]byte
	_, _ = rand.Read(b[:])
	return prefix + base64.RawURLEncoding.EncodeToString(b[:])
}

func sha256Hex(s string) string {
	h := sha256.Sum256([]byte(s))
	return fmt.Sprintf("%x", h[:])
}

/* ----------------------------- auth (JWT minimal) ----------------------------- */

type jwtClaims struct {
	Sub string `json:"sub"`
	Exp int64  `json:"exp"`
}

func (s *server) signJWT(userID string) (string, error) {
	header := base64.RawURLEncoding.EncodeToString([]byte(`{"alg":"HS256","typ":"JWT"}`))
	claims := jwtClaims{Sub: userID, Exp: time.Now().Add(jwtTTL).Unix()}
	cb, _ := json.Marshal(claims)
	payload := base64.RawURLEncoding.EncodeToString(cb)
	msg := header + "." + payload

	mac := hmac.New(sha256.New, jwtKey)
	mac.Write([]byte(msg))
	sig := base64.RawURLEncoding.EncodeToString(mac.Sum(nil))
	return msg + "." + sig, nil
}

func (s *server) verifyJWT(tok string) (jwtClaims, error) {
	parts := strings.Split(tok, ".")
	if len(parts) != 3 {
		return jwtClaims{}, errors.New("bad token")
	}
	msg := parts[0] + "." + parts[1]
	sig, err := base64.RawURLEncoding.DecodeString(parts[2])
	if err != nil {
		return jwtClaims{}, errors.New("bad signature encoding")
	}
	mac := hmac.New(sha256.New, jwtKey)
	mac.Write([]byte(msg))
	if !hmac.Equal(sig, mac.Sum(nil)) {
		return jwtClaims{}, errors.New("bad signature")
	}
	pb, err := base64.RawURLEncoding.DecodeString(parts[1])
	if err != nil {
		return jwtClaims{}, errors.New("bad payload")
	}
	var c jwtClaims
	if json.Unmarshal(pb, &c) != nil {
		return jwtClaims{}, errors.New("bad claims")
	}
	if time.Now().Unix() > c.Exp {
		return jwtClaims{}, errors.New("expired")
	}
	return c, nil
}

type ctxKey string

const ctxUserID ctxKey = "uid"

func (s *server) withAuth(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		tok := ""
		if ah := r.Header.Get("Authorization"); strings.HasPrefix(ah, "Bearer ") {
			tok = strings.TrimSpace(strings.TrimPrefix(ah, "Bearer "))
		}
		if tok == "" {
			if c, _ := r.Cookie("token"); c != nil {
				tok = c.Value
			}
		}
		if tok == "" {
			writeJSON(w, 401, map[string]any{"error": "missing token"})
			return
		}
		claims, err := s.verifyJWT(tok)
		if err != nil {
			writeJSON(w, 401, map[string]any{"error": "invalid token"})
			return
		}
		ctx := context.WithValue(r.Context(), ctxUserID, claims.Sub)
		next(w, r.WithContext(ctx))
	}
}

func uid(r *http.Request) string {
	v, _ := r.Context().Value(ctxUserID).(string)
	return v
}

/* ----------------------------- handlers ----------------------------- */

func (s *server) handleHealth(w http.ResponseWriter, r *http.Request) {
	writeJSON(w, 200, map[string]any{"ok": true, "time": time.Now().Format(time.RFC3339)})
}

func (s *server) handleRegister(w http.ResponseWriter, r *http.Request) {
	if r.Method != "POST" {
		writeJSON(w, 405, map[string]any{"error": "method"})
		return
	}
	var in struct {
		Email    string `json:"email"`
		Password string `json:"password"`
	}
	if err := readJSON(r, &in); err != nil || in.Email == "" || in.Password == "" {
		writeJSON(w, 400, map[string]any{"error": "bad input"})
		return
	}
	email := strings.ToLower(strings.TrimSpace(in.Email))

	s.mu.Lock()
	defer s.mu.Unlock()
	if _, exists := s.usersByEmail[email]; exists {
		writeJSON(w, 409, map[string]any{"error": "exists"})
		return
	}
	u := &user{
		ID:           randID("u_"),
		Email:        email,
		PasswordHash: sha256Hex("salt:" + in.Password),
		CreatedAt:    nowUnix(),
	}
	s.usersByEmail[email] = u
	s.usersByID[u.ID] = u
	s.saveToDisk()
	writeJSON(w, 201, map[string]any{"id": u.ID, "email": u.Email})
}

func (s *server) handleLogin(w http.ResponseWriter, r *http.Request) {
	if r.Method != "POST" {
		writeJSON(w, 405, map[string]any{"error": "method"})
		return
	}
	var in struct {
		Email    string `json:"email"`
		Password string `json:"password"`
	}
	if err := readJSON(r, &in); err != nil {
		writeJSON(w, 400, map[string]any{"error": "bad input"})
		return
	}
	email := strings.ToLower(strings.TrimSpace(in.Email))

	s.mu.RLock()
	u := s.usersByEmail[email]
	s.mu.RUnlock()
	if u == nil || u.PasswordHash != sha256Hex("salt:"+in.Password) {
		writeJSON(w, 401, map[string]any{"error": "bad credentials"})
		return
	}
	tok, _ := s.signJWT(u.ID)
	http.SetCookie(w, &http.Cookie{
		Name:     "token",
		Value:    tok,
		Path:     "/",
		HttpOnly: true,
		SameSite: http.SameSiteLaxMode,
	})
	writeJSON(w, 200, map[string]any{"token": tok})
}

func (s *server) handleMe(w http.ResponseWriter, r *http.Request) {
	s.mu.RLock()
	u := s.usersByID[uid(r)]
	s.mu.RUnlock()
	if u == nil {
		writeJSON(w, 404, map[string]any{"error": "not found"})
		return
	}
	writeJSON(w, 200, map[string]any{"id": u.ID, "email": u.Email, "createdAt": u.CreatedAt})
}

func (s *server) handleProjects(w http.ResponseWriter, r *http.Request) {
	switch r.Method {
	case "GET":
		s.mu.RLock()
		out := []*project{}
		for _, p := range s.projects {
			if p.OwnerID == uid(r) {
				out = append(out, p)
			}
		}
		s.mu.RUnlock()
		sort.Slice(out, func(i, j int) bool { return out[i].CreatedAt > out[j].CreatedAt })
		writeJSON(w, 200, map[string]any{"projects": out})
	case "POST":
		var in struct {
			Name string `json:"name"`
		}
		if err := readJSON(r, &in); err != nil || strings.TrimSpace(in.Name) == "" {
			writeJSON(w, 400, map[string]any{"error": "bad input"})
			return
		}
		p := &project{
			ID:        randID("p_"),
			Name:      strings.TrimSpace(in.Name),
			OwnerID:   uid(r),
			CreatedAt: nowUnix(),
			UpdatedAt: nowUnix(),
		}
		must(os.MkdirAll(p.workDir(), 0o755))
		must(os.MkdirAll(p.snapsDir(), 0o755))
		seedProject(p)

		s.mu.Lock()
		s.projects[p.ID] = p
		if _, ok := s.kv[p.ID]; !ok {
			s.kv[p.ID] = map[string]string{}
		}
		s.mu.Unlock()
		s.saveToDisk()
		writeJSON(w, 201, p)
	default:
		writeJSON(w, 405, map[string]any{"error": "method"})
	}
}

func (s *server) handleProjectByID(w http.ResponseWriter, r *http.Request) {
	// /api/projects/{id}
	id := strings.TrimPrefix(r.URL.Path, "/api/projects/")
	id = strings.Trim(id, "/")
	if id == "" || strings.Contains(id, "/") {
		writeJSON(w, 404, map[string]any{"error": "not found"})
		return
	}
	s.mu.RLock()
	p := s.projects[id]
	s.mu.RUnlock()
	if p == nil || p.OwnerID != uid(r) {
		writeJSON(w, 404, map[string]any{"error": "not found"})
		return
	}
	switch r.Method {
	case "GET":
		writeJSON(w, 200, p)
	case "PATCH":
		var in struct {
			Name *string `json:"name"`
		}
		if err := readJSON(r, &in); err != nil {
			writeJSON(w, 400, map[string]any{"error": "bad input"})
			return
		}
		s.mu.Lock()
		if in.Name != nil && strings.TrimSpace(*in.Name) != "" {
			p.Name = strings.TrimSpace(*in.Name)
			p.UpdatedAt = nowUnix()
		}
		s.mu.Unlock()
		s.saveToDisk()
		writeJSON(w, 200, p)
	case "DELETE":
		s.mu.Lock()
		delete(s.projects, id)
		delete(s.kv, id)
		delete(s.docs, id)
		s.mu.Unlock()
		_ = os.RemoveAll(filepath.Join(projectRoot, id))
		s.saveToDisk()
		writeJSON(w, 200, map[string]any{"deleted": true})
	default:
		writeJSON(w, 405, map[string]any{"error": "method"})
	}
}

func (s *server) handleProjectSubroutes(w http.ResponseWriter, r *http.Request) {
	// Handles:
	// /api/projects/{id}/files (GET, PUT)
	// /api/projects/{id}/snapshots (GET, POST) ; /api/projects/{id}/snapshots/{sid}/restore (POST)
	// /api/projects/{id}/kv (GET, PUT)
	// /api/projects/{id}/nix/apply (POST)
	// /api/projects/{id}/deploy (POST)
	// /api/projects/{id}/agent/run (POST)

	path := strings.TrimPrefix(r.URL.Path, "/api/projects/")
	parts := strings.Split(strings.Trim(path, "/"), "/")
	if len(parts) < 2 {
		return // let other handler serve
	}
	pid := parts[0]
	s.mu.RLock()
	p := s.projects[pid]
	s.mu.RUnlock()
	if p == nil || p.OwnerID != uid(r) {
		writeJSON(w, 404, map[string]any{"error": "not found"})
		return
	}
	switch parts[1] {
	case "files":
		s.handleFiles(p, w, r)
	case "snapshots":
		s.handleSnapshots(p, parts[2:], w, r)
	case "kv":
		s.handleKV(p, w, r)
	case "nix":
		if len(parts) >= 3 && parts[2] == "apply" {
			s.handleNixApply(p, w, r)
			return
		}
		writeJSON(w, 404, map[string]any{"error": "not found"})
	case "deploy":
		s.handleDeploy(p, w, r)
	case "agent":
		if len(parts) >= 3 && parts[2] == "run" {
			s.handleAgentRun(p, w, r)
			return
		}
		writeJSON(w, 404, map[string]any{"error": "not found"})
	default:
		writeJSON(w, 404, map[string]any{"error": "not found"})
	}
}

/* ----------------------------- files API ----------------------------- */

func (s *server) handleFiles(p *project, w http.ResponseWriter, r *http.Request) {
	switch r.Method {
	case "GET":
		rel := strings.TrimPrefix(r.URL.Query().Get("path"), "/")
		if rel == "" {
			rel = "."
		}
		full := safeJoin(p.workDir(), rel)
		if full == "" {
			writeJSON(w, 400, map[string]any{"error": "bad path"})
			return
		}
		st, err := os.Stat(full)
		if err != nil {
			writeJSON(w, 404, map[string]any{"error": "not found"})
			return
		}
		if st.IsDir() {
			ents, _ := os.ReadDir(full)
			type item struct {
				Name string `json:"name"`
				Path string `json:"path"`
				Dir  bool   `json:"dir"`
				Size int64  `json:"size"`
			}
			out := []item{}
			for _, e := range ents {
				inf, _ := e.Info()
				out = append(out, item{
					Name: e.Name(),
					Path: strings.TrimPrefix(filepath.ToSlash(filepath.Join(rel, e.Name())), "./"),
					Dir:  e.IsDir(),
					Size: func() int64 {
						if inf == nil {
							return 0
						}
						return inf.Size()
					}(),
				})
			}
			sort.Slice(out, func(i, j int) bool {
				if out[i].Dir != out[j].Dir {
					return out[i].Dir
				}
				return out[i].Name < out[j].Name
			})
			writeJSON(w, 200, map[string]any{"items": out})
			return
		}
		b, _ := os.ReadFile(full)
		writeJSON(w, 200, map[string]any{"path": rel, "content": string(b)})
	case "PUT":
		var in struct {
			Path    string `json:"path"`
			Content string `json:"content"`
		}
		if err := readJSON(r, &in); err != nil || strings.TrimSpace(in.Path) == "" {
			writeJSON(w, 400, map[string]any{"error": "bad input"})
			return
		}
		rel := strings.TrimPrefix(in.Path, "/")
		full := safeJoin(p.workDir(), rel)
		if full == "" {
			writeJSON(w, 400, map[string]any{"error": "bad path"})
			return
		}
		must(os.MkdirAll(filepath.Dir(full), 0o755))
		if err := os.WriteFile(full, []byte(in.Content), 0o644); err != nil {
			writeJSON(w, 500, map[string]any{"error": "write failed"})
			return
		}
		writeJSON(w, 200, map[string]any{"ok": true})
	default:
		writeJSON(w, 405, map[string]any{"error": "method"})
	}
}

func safeJoin(root, rel string) string {
	clean := filepath.Clean(rel)
	if strings.HasPrefix(clean, "..") || strings.Contains(clean, ":") {
		return ""
	}
	full := filepath.Join(root, clean)
	absRoot, _ := filepath.Abs(root)
	absFull, _ := filepath.Abs(full)
	if !strings.HasPrefix(absFull, absRoot) {
		return ""
	}
	return full
}

/* ----------------------------- snapshot API ----------------------------- */

func (s *server) handleSnapshots(p *project, tail []string, w http.ResponseWriter, r *http.Request) {
	// /snapshots (GET, POST)
	// /snapshots/{sid}/restore (POST)
	if len(tail) == 0 {
		switch r.Method {
		case "GET":
			ents, _ := os.ReadDir(p.snapsDir())
			out := []map[string]any{}
			for _, e := range ents {
				if !e.IsDir() {
					continue
				}
				inf, _ := e.Info()
				out = append(out, map[string]any{
					"id":        e.Name(),
					"createdAt": func() int64 { if inf == nil { return 0 }; return inf.ModTime().Unix() }(),
				})
			}
			sort.Slice(out, func(i, j int) bool { return out[i]["createdAt"].(int64) > out[j]["createdAt"].(int64) })
			writeJSON(w, 200, map[string]any{"snapshots": out})
		case "POST":
			var in struct {
				Label string `json:"label"`
			}
			_ = readJSON(r, &in)
			sid := randID("s_")
			dst := filepath.Join(p.snapsDir(), sid)
			if err := snapshotDirHardlink(p.workDir(), dst); err != nil {
				writeJSON(w, 500, map[string]any{"error": "snapshot failed", "detail": err.Error()})
				return
			}
			if strings.TrimSpace(in.Label) != "" {
				_ = os.WriteFile(filepath.Join(dst, ".label"), []byte(strings.TrimSpace(in.Label)), 0o644)
			}
			writeJSON(w, 201, map[string]any{"id": sid})
		default:
			writeJSON(w, 405, map[string]any{"error": "method"})
		}
		return
	}
	if len(tail) == 2 && tail[1] == "restore" && r.Method == "POST" {
		sid := tail[0]
		src := filepath.Join(p.snapsDir(), sid)
		if st, err := os.Stat(src); err != nil || !st.IsDir() {
			writeJSON(w, 404, map[string]any{"error": "snapshot not found"})
			return
		}
		tmp := p.workDir() + ".restore_tmp"
		_ = os.RemoveAll(tmp)
		if err := snapshotDirHardlink(src, tmp); err != nil {
			writeJSON(w, 500, map[string]any{"error": "restore failed", "detail": err.Error()})
			return
		}
		_ = os.RemoveAll(p.workDir())
		must(os.Rename(tmp, p.workDir()))
		writeJSON(w, 200, map[string]any{"ok": true})
		return
	}
	writeJSON(w, 404, map[string]any{"error": "not found"})
}

func snapshotDirHardlink(src, dst string) error {
	_ = os.RemoveAll(dst)
	if err := os.MkdirAll(dst, 0o755); err != nil {
		return err
	}
	return filepath.WalkDir(src, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		rel, _ := filepath.Rel(src, path)
		if rel == "." {
			return nil
		}
		target := filepath.Join(dst, rel)
		if d.IsDir() {
			return os.MkdirAll(target, 0o755)
		}
		if d.Type()&os.ModeSymlink != 0 {
			link, _ := os.Readlink(path)
			return os.Symlink(link, target)
		}
		// hardlink files for speed (fallback to copy if needed)
		if err := os.Link(path, target); err == nil {
			return nil
		}
		b, err := os.ReadFile(path)
		if err != nil {
			return err
		}
		return os.WriteFile(target, b, 0o644)
	})
}

