/* ----------------------------- WebSocket minimal ----------------------------- */

type wsConn struct {
	c   net.Conn
	rw  *bufioRW
	mu  sync.Mutex
	cls chan struct{}
}

type bufioRW struct {
	r *bufioReader
	w *bufioWriter
}

type bufioReader struct{ *bytes.Reader } // placeholder; upgraded after hijack
type bufioWriter struct{ io.Writer }

func (wc *wsConn) Close() error {
	select {
	case <-wc.cls:
		return nil
	default:
		close(wc.cls)
	}
	return wc.c.Close()
}

// NOTE: To keep this single-file and dependency-free, implement a tiny subset of RFC6455:
// - text frames only
// - client->server masked required
// - server->client unmasked
// - no fragmentation
// This is enough for local/dev and MVP-like use.

func wsUpgrade(w http.ResponseWriter, r *http.Request) (*wsConn, error) {
	if strings.ToLower(r.Header.Get("Connection")) != "upgrade" ||
		strings.ToLower(r.Header.Get("Upgrade")) != "websocket" {
		return nil, errors.New("not websocket upgrade")
	}
	key := r.Header.Get("Sec-WebSocket-Key")
	if key == "" {
		return nil, errors.New("missing key")
	}
	accept := wsAcceptKey(key)
	h, ok := w.(http.Hijacker)
	if !ok {
		return nil, errors.New("no hijack")
	}
	c, buf, err := h.Hijack()
	if err != nil {
		return nil, err
	}
	resp := "HTTP/1.1 101 Switching Protocols\r\n" +
		"Upgrade: websocket\r\n" +
		"Connection: Upgrade\r\n" +
		"Sec-WebSocket-Accept: " + accept + "\r\n\r\n"
	if _, err := buf.WriteString(resp); err != nil {
		_ = c.Close()
		return nil, err
	}
	if err := buf.Flush(); err != nil {
		_ = c.Close()
		return nil, err
	}
	return &wsConn{c: c, cls: make(chan struct{})}, nil
}

func wsAcceptKey(key string) string {
	const magic = "258EAFA5-E914-47DA-95CA-C5AB0DC85B11"
	h := sha1Sum([]byte(key + magic))
	return base64.StdEncoding.EncodeToString(h)
}

func sha1Sum(b []byte) []byte {
	// Minimal SHA1 using crypto/sha1 would be standard lib, use it.
	h := sha1.New()
	h.Write(b)
	return h.Sum(nil)
}

func (wc *wsConn) ReadText() (string, error) {
	// Read header (2 bytes)
	hdr := make([]byte, 2)
	if _, err := io.ReadFull(wc.c, hdr); err != nil {
		return "", err
	}
	fin := hdr[0]&0x80 != 0
	op := hdr[0] & 0x0F
	if !fin || op != 0x1 {
		return "", errors.New("unsupported frame")
	}
	masked := hdr[1]&0x80 != 0
	ln := int(hdr[1] & 0x7F)
	if ln == 126 {
		ext := make([]byte, 2)
		if _, err := io.ReadFull(wc.c, ext); err != nil {
			return "", err
		}
		ln = int(ext[0])<<8 | int(ext[1])
	} else if ln == 127 {
		return "", errors.New("too large")
	}
	var maskKey [4]byte
	if masked {
		if _, err := io.ReadFull(wc.c, maskKey[:]); err != nil {
			return "", err
		}
	} else {
		return "", errors.New("client frames must be masked")
	}
	if ln > wsMaxMessageBytes {
		return "", errors.New("message too large")
	}
	payload := make([]byte, ln)
	if _, err := io.ReadFull(wc.c, payload); err != nil {
		return "", err
	}
	for i := 0; i < ln; i++ {
		payload[i] ^= maskKey[i%4]
	}
	return string(payload), nil
}

func (wc *wsConn) WriteText(s string) error {
	wc.mu.Lock()
	defer wc.mu.Unlock()

	b := []byte(s)
	if len(b) > wsMaxMessageBytes {
		b = b[:wsMaxMessageBytes]
	}
	var buf bytes.Buffer
	// FIN + text
	buf.WriteByte(0x81)
	if len(b) < 126 {
		buf.WriteByte(byte(len(b)))
	} else {
		buf.WriteByte(126)
		buf.WriteByte(byte(len(b) >> 8))
		buf.WriteByte(byte(len(b)))
	}
	buf.Write(b)
	_, err := wc.c.Write(buf.Bytes())
	return err
}

