type docState struct {
	Version int    `json:"version"`
	Text    string `json:"text"`
}

type syncHub struct {
	s    *server
	mu   sync.RWMutex
	subs map[string]map[*wsConn]struct{} // key=projectID|filePath
}

func newSyncHub(s *server) *syncHub {
	return &syncHub{s: s, subs: map[string]map[*wsConn]struct{}{}}
}

func (h *syncHub) run() { select {} }

func (h *syncHub) subscribe(key string, c *wsConn) {
	h.mu.Lock()
	defer h.mu.Unlock()
	if h.subs[key] == nil {
		h.subs[key] = map[*wsConn]struct{}{}
	}
	h.subs[key][c] = struct{}{}
}

func (h *syncHub) unsubscribeAll(c *wsConn) {
	h.mu.Lock()
	defer h.mu.Unlock()
	for k := range h.subs {
		delete(h.subs[k], c)
		if len(h.subs[k]) == 0 {
			delete(h.subs, k)
		}
	}
}

func (h *syncHub) broadcast(key string, msg string) {
	h.mu.RLock()
	defer h.mu.RUnlock()
	for c := range h.subs[key] {
		_ = c.WriteText(msg)
	}
}

func (s *server) handleWSSync(w http.ResponseWriter, r *http.Request) {
	// Query: project, file
	pid := r.URL.Query().Get("project")
	file := r.URL.Query().Get("file")
	if pid == "" || file == "" {
		writeJSON(w, 400, map[string]any{"error": "missing project/file"})
		return
	}
	s.mu.RLock()
	p := s.projects[pid]
	s.mu.RUnlock()
	if p == nil || p.OwnerID != uid(r) {
		writeJSON(w, 404, map[string]any{"error": "not found"})
		return
	}

	c, err := wsUpgrade(w, r)
	if err != nil {
		writeJSON(w, 400, map[string]any{"error": "ws upgrade failed"})
		return
	}
	defer c.Close()

	key := pid + "|" + file
	s.syncHub.subscribe(key, c)
	defer s.syncHub.unsubscribeAll(c)

	// Load doc from disk initially
	full := safeJoin(p.workDir(), file)
	if full == "" {
		_ = c.WriteText(`{"type":"err","error":"bad path"}`)
		return
	}
	b, _ := os.ReadFile(full)
	doc := s.getOrInitDoc(pid, file, string(b))
	_ = c.WriteText(mustJSON(map[string]any{"type": "init", "version": doc.Version, "text": doc.Text}))

	for {
		msg, err := c.ReadText()
		if err != nil {
			return
		}
		var in map[string]any
		if json.Unmarshal([]byte(msg), &in) != nil {
			continue
		}
		if in["type"] == "op" {
			s.applyOpAndBroadcast(p, pid, file, in)
		}
	}
}

func (s *server) getOrInitDoc(pid, file, initial string) *docState {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.docs[pid] == nil {
		s.docs[pid] = map[string]*docState{}
	}
	if s.docs[pid][file] == nil {
		s.docs[pid][file] = &docState{Version: 1, Text: initial}
	}
	return s.docs[pid][file]
}

func (s *server) applyOpAndBroadcast(p *project, pid, file string, in map[string]any) {
	// Input: {type:"op", baseVersion:int, pos:int, del:int, ins:string}
	baseV, _ := toInt(in["baseVersion"])
	pos, _ := toInt(in["pos"])
	del, _ := toInt(in["del"])
	ins, _ := in["ins"].(string)

	s.mu.Lock()
	doc := s.getOrInitDoc(pid, file, "")
	curV := doc.Version
	if baseV != curV {
		// Resync: send full doc
		out := mustJSON(map[string]any{"type": "resync", "version": doc.Version, "text": doc.Text})
		s.mu.Unlock()
		s.syncHub.broadcast(pid+"|"+file, out)
		return
	}
	if pos < 0 {
		pos = 0
	}
	if pos > len(doc.Text) {
		pos = len(doc.Text)
	}
	if del < 0 {
		del = 0
	}
	if pos+del > len(doc.Text) {
		del = len(doc.Text) - pos
	}
	doc.Text = doc.Text[:pos] + ins + doc.Text[pos+del:]
	doc.Version++

	// Persist to disk
	full := safeJoin(p.workDir(), file)
	if full != "" {
		_ = os.MkdirAll(filepath.Dir(full), 0o755)
		_ = os.WriteFile(full, []byte(doc.Text), 0o644)
	}
	out := mustJSON(map[string]any{
		"type":       "opApplied",
		"version":    doc.Version,
		"baseVersion": baseV,
		"pos":        pos,
		"del":        del,
		"ins":        ins,
	})
	s.mu.Unlock()
	s.syncHub.broadcast(pid+"|"+file, out)
}

func toInt(v any) (int, bool) {
	switch t := v.(type) {
	case float64:
		return int(t), true
	case int:
		return t, true
	case string:
		i, err := strconv.Atoi(t)
		return i, err == nil
	default:
		return 0, false
	}
}

func mustJSON(v any) string {
	b, _ := json.Marshal(v)
	return string(b)
}

