func runInProject(dir, command string, preferNix bool) (string, int) {
	command = strings.TrimSpace(command)
	if command == "" {
		return "", 0
	}
	ctx, cancel := context.WithTimeout(context.Background(), 60*time.Second)
	defer cancel()

	// crude check for nix presence
	if preferNix && command != "" && hasExe("nix") {
		// nix develop -c <shell> -lc "<command>"
		cmd := exec.CommandContext(ctx, "nix", "develop", "-c", "sh", "-lc", command)
		cmd.Dir = dir
		var buf bytes.Buffer
		cmd.Stdout, cmd.Stderr = &buf, &buf
		err := cmd.Run()
		return buf.String(), exitCode(err)
	}

	cmd := exec.CommandContext(ctx, "sh", "-lc", command)
	cmd.Dir = dir
	var buf bytes.Buffer
	cmd.Stdout, cmd.Stderr = &buf, &buf
	err := cmd.Run()
	return buf.String(), exitCode(err)
}

func hasExe(name string) bool {
	_, err := exec.LookPath(name)
	return err == nil
}

func exitCode(err error) int {
	if err == nil {
		return 0
	}
	var ee *exec.ExitError
	if errors.As(err, &ee) {
		return ee.ExitCode()
	}
	return 1
}

